const body = $input.first().json.body || $input.first().json;
const rawMessage = (body.message || body.text || body.input || '').trim();
if (!rawMessage) {
  throw new Error('No message provided. Shortcut should POST { message: "..." }');
}
const lower = rawMessage.toLowerCase();
const wantsFull = /full rundown|go deep|full detail|tell me everything|long version|elaborate/.test(lower);
let message = rawMessage;
if (wantsFull) {
  message = rawMessage.replace(/(give me the |the )?(full rundown|go deep|full detail|tell me everything|long version|elaborate)[.!,]?/gi, '').trim() || rawMessage;
}
const verbosity = wantsFull ? 'full' : 'brief';
return [{ json: { message, verbosity, sessionId: 'siri-home', channel: 'voice' } }];

const jarvis = $input.first().json;
const verbosity = $('Normalize Siri Input').first().json.verbosity;
let reply = jarvis.response || jarvis.assistant_response || 'Sorry, I did not get a response.';
reply = reply
  .replace(/[*_`#>]/g, '')
  .replace(/\[(.*?)\]\(.*?\)/g, '$1')
  .replace(/\n{2,}/g, '. ')
  .replace(/\n/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim();
if (verbosity === 'brief') {
  const sentences = reply.match(/[^.!?]+[.!?]+/g) || [reply];
  reply = sentences.slice(0, 3).join(' ').trim();
}
return [{ json: { reply } }];

const body = $input.first().json.body || $input.first().json;
const req = body.request || {};
const intent = req.intent || {};
const slots = intent.slots || {};
const rawMessage = (slots.query && slots.query.value) || body.message || '';
const requestType = req.type || 'IntentRequest';
const sessionId = 'alexa-home';
let control = null;
if (requestType === 'LaunchRequest') control = 'launch';
if (intent.name === 'AMAZON.StopIntent' || intent.name === 'AMAZON.CancelIntent') control = 'stop';
if (intent.name === 'AMAZON.HelpIntent') control = 'help';
if (!rawMessage && !control) control = 'empty';
const lower = (rawMessage || '').toLowerCase();
const wantsFull = /full rundown|go deep|full detail|tell me everything|long version|elaborate/.test(lower);
let message = rawMessage;
if (wantsFull) {
  message = rawMessage.replace(/(give me the |the )?(full rundown|go deep|full detail|tell me everything|long version|elaborate)[.!,]?/gi, '').trim() || rawMessage;
}
const verbosity = wantsFull ? 'full' : 'brief';
const isControl = control !== null;
return [{ json: { message, verbosity, sessionId, channel: 'voice', control, isControl } }];

const verbosity = $('Normalize Alexa Input').first().json.verbosity;
const jarvis = $input.first().json;
let reply = jarvis.response || jarvis.assistant_response || 'I could not get an answer just now.';
reply = reply
  .replace(/[*_`#>]/g, '')
  .replace(/\[(.*?)\]\(.*?\)/g, '$1')
  .replace(/&/g, 'and')
  .replace(/</g, ' ').replace(/>/g, ' ')
  .replace(/\n{2,}/g, '. ')
  .replace(/\n/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim();
if (verbosity === 'brief') {
  const sentences = reply.match(/[^.!?]+[.!?]+/g) || [reply];
  reply = sentences.slice(0, 3).join(' ').trim();
}
return [{ json: { version: '1.0', response: { outputSpeech: { type: 'PlainText', text: reply }, shouldEndSession: false } } }];

const control = $json.control;
let speech;
let endSession = false;
if (control === 'launch') {
  speech = 'Cosmo here. What do you need?';
} else if (control === 'help') {
  speech = 'Ask me about your schedule, your work tasks, your job search, or anything you are building. Say give me the full rundown if you want the long version.';
} else if (control === 'stop') {
  speech = 'Talk soon.';
  endSession = true;
} else {
  speech = 'I did not catch that. Can you say it again?';
}
return [{ json: { version: '1.0', response: { outputSpeech: { type: 'PlainText', text: speech }, shouldEndSession: endSession } } }];
